static int aa_fs_seq_show ( struct seq_file * seq , void * v ) { struct aa_fs_entry * fs_file = seq -> private ; switch ( fs_file -> v_type ) { case AA_FS_TYPE_BOOLEAN : seq_printf ( seq , "%s\n" , fs_file -> v . boolean ?"yes" : "no" ) ; break ; case AA_FS_TYPE_STRING : seq_printf ( seq , "%s\n" , fs_file -> v . string ) ; break ; case AA_FS_TYPE_U64 : seq_printf ( seq , "%#08lx\n" , fs_file -> v . u64 ) ; break ; default : break ; } return 0 ; } 